import{_ as t,o,c as d,a3 as a}from"./chunks/framework.DAK02U1-.js";const p=JSON.parse('{"title":"Handler protocol","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Handler protocol | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/catter/design/handler-protocol"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/catter/design/handler-protocol"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/catter/design/handler-protocol"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/catter/design/handler-protocol"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/catter/design/handler-protocol"}]]},"headers":[],"relativePath":"catter/design/handler-protocol.md","filePath":"en/catter/design/handler-protocol.md","lastUpdated":1793198831000}'),c={name:"catter/design/handler-protocol.md"};function r(n,e,s,i,h,l){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="handler-protocol" tabindex="-1">Handler protocol <a class="header-anchor" href="#handler-protocol" aria-label="Permalink to &quot;Handler protocol&quot;">​</a></h1><p>This page specifies the protocol between catter and a <a href="./../scripting/handlers">handler</a>, for writing a handler without an SDK. The SDKs implement it, with types generated from the same definition catter&#39;s are.</p><h2 id="transport" tabindex="-1">Transport <a class="header-anchor" href="#transport" aria-label="Permalink to &quot;Transport&quot;">​</a></h2><p>Messages are <a href="https://www.jsonrpc.org/specification" target="_blank" rel="noreferrer">JSON-RPC 2.0</a>, each framed as the Language Server Protocol frames them: a <code>Content-Length: &lt;n&gt;</code> header, an empty line (<code>\\r\\n\\r\\n</code>), then <code>n</code> bytes of UTF-8 JSON.</p><ul><li>A handler catter starts (<code>--handler</code>) reads catter&#39;s messages on its stdin and writes its own on its stdout. Its stderr is the terminal&#39;s.</li><li>A handler that listens (<code>--connect</code>) does the same over each TCP connection: one connection is one session.</li></ul><p>catter sends requests and notifications; a handler answers the requests and may send requests of its own, <code>analyze</code>, which catter answers (another method with an error), but no notifications. Beside the messages below, catter may send <code>$/cancelRequest</code>, as the Language Server Protocol does, for a request it no longer waits for: a handler may ignore it.</p><h2 id="a-session" tabindex="-1">A session <a class="header-anchor" href="#a-session" aria-label="Permalink to &quot;A session&quot;">​</a></h2><ol><li><code>initialize</code> (request): the session starts. The handler answers with what it wants to be told.</li><li>While the build runs, for each command: <code>command</code>, a request to a handler that decides and a notification to one that does not; <code>error</code> when catter could not capture a command; <code>exit</code> once a command has run. Notifications arrive only if the handler asked for them.</li><li><code>finish</code> (request): the build has ended. Once the handler has answered, catter ends its input: a handler it started then exits; over TCP, catter shuts down its side of the connection, and the handler closes it.</li></ol><p>Commands of a parallel build overlap: <code>command</code> requests can be in flight together, and are answered by their ids, in any order.</p><h2 id="messages" tabindex="-1">Messages <a class="header-anchor" href="#messages" aria-label="Permalink to &quot;Messages&quot;">​</a></h2><h3 id="initialize" tabindex="-1"><code>initialize</code> <a class="header-anchor" href="#initialize" aria-label="Permalink to &quot;`initialize`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>version</code></td><td>integer</td><td>The protocol&#39;s version: <code>1</code>.</td></tr><tr><td><code>session</code></td><td>string</td><td>Tells apart the sessions one handler serves over TCP.</td></tr><tr><td><code>mode</code></td><td>string</td><td>The capture backend: <code>hook</code>, <code>wrapper</code>, <code>eslogger</code>, <code>ptrace</code>, or <code>replay</code>.</td></tr><tr><td><code>decisions</code></td><td>boolean</td><td>Each command waits for the answer of a handler that decides: false under a backend that only observes them, <code>eslogger</code> or <code>ptrace</code>, which refuses such a handler. Under <code>replay</code> the answers change nothing, as nothing runs.</td></tr><tr><td><code>build.command</code></td><td>OS string array</td><td>The build command.</td></tr><tr><td><code>build.cwd</code></td><td>OS string</td><td>Its working directory.</td></tr></tbody></table><p>The result:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>decides</code></td><td>boolean</td><td>Every command comes as a request, which the build waits for.</td></tr><tr><td><code>events.command</code></td><td>boolean</td><td>A handler that does not decide is told of each command.</td></tr><tr><td><code>events.error</code></td><td>boolean</td><td>The handler is told of the commands catter could not capture.</td></tr><tr><td><code>events.exit</code></td><td>boolean</td><td>The handler is told of each command&#39;s exit.</td></tr><tr><td><code>env</code></td><td>boolean</td><td>Commands carry their environment.</td></tr><tr><td><code>analysis</code></td><td>boolean</td><td>Commands carry what catter makes of them (below).</td></tr><tr><td><code>filter</code></td><td>pattern array, optional</td><td>The handler is told only of the commands a pattern names, and of their exits; to a handler that decides, the others are as <code>skip</code>. Every command when absent.</td></tr></tbody></table><p>A pattern names commands by what catter makes of them:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>kind</code></td><td>string</td><td>The kind of program they run: <code>compiler</code>, <code>archiver</code> or <code>tool</code>.</td></tr><tr><td><code>names</code></td><td>string array, optional</td><td>Of compilers and tools, their names (<code>gcc</code>, <code>clang</code>, <code>clang-cl</code>, <code>msvc</code>, <code>nvcc</code>; <code>lld-elf</code>, …). Any when absent.</td></tr><tr><td><code>phases</code></td><td>string array, optional</td><td>Of compilers, the phases of their commands (<code>preprocess</code>, <code>syntax-only</code>, <code>compile</code>, <code>link</code>, …). Any when absent.</td></tr></tbody></table><p>A command whose arguments catter cannot read has no phase: a pattern with <code>phases</code> does not name it.</p><h3 id="command" tabindex="-1"><code>command</code> <a class="header-anchor" href="#command" aria-label="Permalink to &quot;`command`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>The command&#39;s id in the session.</td></tr><tr><td><code>parent</code></td><td>integer, optional</td><td>The command that started it; absent for the build command.</td></tr><tr><td><code>cwd</code></td><td>OS string</td><td>Its working directory.</td></tr><tr><td><code>executable</code></td><td>OS string</td><td>The program it runs.</td></tr><tr><td><code>args</code></td><td>OS string array</td><td>Its arguments, the program&#39;s name first.</td></tr><tr><td><code>env</code></td><td>OS string array, optional</td><td>Its environment, <code>NAME=value</code> entries, if the handler asked.</td></tr><tr><td><code>analysis</code></td><td>analysis, optional</td><td>What catter makes of it, if the handler asked; absent for a program catter knows nothing of.</td></tr></tbody></table><p>The result of the request is an action, named by its <code>action</code> field:</p><table tabindex="0"><thead><tr><th><code>action</code></th><th>Fields</th><th>What catter does</th></tr></thead><tbody><tr><td><code>skip</code></td><td></td><td>Runs the command as it is.</td></tr><tr><td><code>drop</code></td><td></td><td>Does not run it: it exits 0.</td></tr><tr><td><code>abort</code></td><td><code>reason</code>: string</td><td>Ends the session (below), reporting the reason.</td></tr><tr><td><code>modify</code></td><td><code>args</code>, and optionally <code>executable</code>, <code>cwd</code>, <code>env</code></td><td>Runs the command with these in place of its own; a field left out keeps the command&#39;s.</td></tr><tr><td><code>edit</code></td><td><code>edits</code>: edit array</td><td>Runs the command with its arguments edited (below).</td></tr></tbody></table><h3 id="analysis" tabindex="-1">Analysis <a class="header-anchor" href="#analysis" aria-label="Permalink to &quot;Analysis&quot;">​</a></h3><p>What catter makes of a command, named by its <code>kind</code>. catter knows a program by its executable&#39;s name, perhaps after a target (<code>x86_64-linux-gnu-gcc</code>) and before a version (<code>gcc-13</code>, <code>llvm-ar-18</code>, MacPorts&#39; <code>clang-mp-18</code>): <code>cc</code> and <code>c++</code> are <code>gcc</code>, even where they run clang.</p><ul><li><code>compiler</code>: a command of gcc, clang, clang-cl or MSVC&#39;s cl. <code>compiler</code>; <code>dialect</code>, the syntax its arguments are read in (<code>gcc</code>, <code>clang</code>, or <code>msvc</code>, clang&#39;s in cl mode too); <code>phase</code> and <code>artifact</code>, what it makes; <code>target</code> (<code>triple</code>, <code>os</code>, <code>objectFormat</code>, <code>env</code>, <code>artifactModel</code>, <code>source</code>: what tells the target); <code>expansion</code>, when the command names response files (<code>@file</code>) catter read: <code>files</code>, those it read, as named, the files they name too, and <code>args</code>, the command&#39;s arguments with them read in, which the indices below count in; <code>arguments</code>; <code>reads</code>, each with <code>path</code>, <code>argument</code> and <code>index</code> (where the command names it), <code>role</code> (<code>source</code> or <code>link</code>) and a source&#39;s <code>language</code>; <code>writes</code>, each with <code>path</code>, <code>reads</code> (the reads it is made from) and <code>origin</code>; and <code>diagnostics</code>, how catter inferred the files where the arguments leave them open.</li><li><code>archiver</code>: a command of <code>ar</code>, <code>gcc-ar</code> or <code>llvm-ar</code>. <code>operation</code>, <code>modifiers</code>, <code>thin</code>, <code>archive</code>, <code>members</code>, <code>reads</code> and <code>writes</code>.</li><li><code>tool</code>: a command of a linker or a librarian, whose arguments catter reads by its option table, <code>tool</code>: <code>lld-elf</code>, <code>lld-coff</code>, <code>lld-macho</code>, <code>lld-mingw</code>, <code>lld-wasm</code>, <code>llvm-lib</code> or <code>llvm-dlltool</code>; <code>lld-coff</code> and <code>llvm-lib</code> take options in any case, as <code>link.exe</code> and <code>lib.exe</code> do. <code>arguments</code>, a response file among them as the command names it: catter reads no tool&#39;s response files.</li><li><code>unparsed</code>: a command of such a program whose arguments catter cannot read, nvcc&#39;s for now. <code>of</code>, the kind of program, <code>name</code>, <code>error</code> and <code>message</code>.</li></ul><p>Each argument has <code>option</code>, the option it is after aliases, by its name with its prefix (<code>-I</code> for <code>/I</code> too; <code>&lt;input&gt;</code> for an input, <code>&lt;unknown&gt;</code> for an option the option table does not know, with the value after it for those of GCC and cl that take one: <code>-dumpbase</code>, <code>/ifcOutput</code>, …); <code>spelling</code>, as the command writes it (<code>-msmall-data-limit=</code> of what is <code>-G</code>); <code>index</code> and <code>count</code>, the command&#39;s arguments it takes; and <code>values</code>.</p><p>A source&#39;s language is named as <code>-x</code> names it (<code>c</code>, <code>c++</code>, <code>c++-module</code>, <code>objective-c</code>, <code>assembler</code>, <code>cuda</code>, …): the one <code>/Tc</code> or <code>/Tp</code> names it with, the one the last <code>-x</code> before it sets (<code>-x none</code> resets it), the one <code>/TC</code> or <code>/TP</code> sets, else its suffix&#39;s, <code>.C</code>, <code>.M</code> and <code>.S</code> naming other languages than in lower case but to cl, and <code>.c</code> and <code>.i</code> C++ to a C++ driver (<code>g++</code>, <code>c++</code>, <code>clang++</code>, <code>--driver-mode=g++</code>). An input after <code>-x</code>, or with <code>/TC</code> or <code>/TP</code>, is a source of its language whatever its suffix, but an object or a library.</p><h3 id="edits" tabindex="-1">Edits <a class="header-anchor" href="#edits" aria-label="Permalink to &quot;Edits&quot;">​</a></h3><p>The edits of <code>edit</code> are made in turn. Each has <code>kind</code> and <code>flags</code>: arguments written as the command&#39;s program takes them.</p><table tabindex="0"><thead><tr><th><code>kind</code></th><th>What it does</th></tr></thead><tbody><tr><td><code>remove</code></td><td>Takes out the arguments the flags name, and those an edit before it added: <code>-DX</code> the arguments <code>-DX</code> (<code>-DX=1</code> has another value), <code>-D*</code> (or <code>-D</code> last) every definition, <code>-W*</code> every option of <code>-W</code>&#39;s group written with <code>-W</code> first. An option the table does not know is named as written, <code>=*</code> after it for any value, and one of those that take a separate value (<code>-dumpbase</code>, <code>/ifcOutput</code>) alone for any value.</td></tr><tr><td><code>append</code></td><td>Adds the flags after the command&#39;s own arguments, where they take effect over them and libraries go: before <code>--</code> and <code>/link</code>, which end the options.</td></tr><tr><td><code>prepend</code></td><td>Adds the flags right after the program.</td></tr></tbody></table><p>The arguments no edit takes out keep the command&#39;s own spelling, and the added flags go as they are: catter writes no argument anew. A compiler&#39;s response file stays as the command names it unless an edit takes out an argument it holds or adds flags among them, which puts the arguments it holds in its place. Only a command whose arguments catter reads can be edited: a compiler&#39;s or a tool&#39;s, not <code>unparsed</code>.</p><h3 id="analyze" tabindex="-1"><code>analyze</code> <a class="header-anchor" href="#analyze" aria-label="Permalink to &quot;`analyze`&quot;">​</a></h3><p>A request a handler sends catter, for what catter makes of commands of its own: <code>programs</code>, each with <code>executable</code>, <code>args</code> (the program&#39;s name first) and, optionally, <code>cwd</code>, the directory it runs in, which its relative response files are read from: without it, only its absolute ones are read. The result is <code>analyses</code>, one for each, <code>null</code> for a program catter knows nothing of.</p><h3 id="error-exit-and-finish" tabindex="-1"><code>error</code>, <code>exit</code> and <code>finish</code> <a class="header-anchor" href="#error-exit-and-finish" aria-label="Permalink to &quot;`error`, `exit` and `finish`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Message</th><th>Fields</th></tr></thead><tbody><tr><td><code>error</code></td><td><code>id</code>, <code>parent</code> (optional), <code>message</code>: why catter could not capture the command.</td></tr><tr><td><code>exit</code></td><td><code>id</code>, <code>code</code>: its exit code, 128 and the signal&#39;s number for one a signal ended, <code>duration</code>: how long the command ran, in microseconds, as the capture backend measures it (<code>0</code> under <code>replay</code>).</td></tr><tr><td><code>finish</code></td><td><code>code</code>: the build&#39;s exit code, as <code>exit</code>&#39;s. The result is <code>null</code>.</td></tr></tbody></table><h2 id="strings-and-numbers" tabindex="-1">Strings and numbers <a class="header-anchor" href="#strings-and-numbers" aria-label="Permalink to &quot;Strings and numbers&quot;">​</a></h2><ul><li><strong>OS strings.</strong> An argument, a path or an environment entry is a JSON string when its bytes are valid UTF-8, and <code>{&quot;base64&quot;: &quot;&lt;the bytes in base64&gt;&quot;}</code> otherwise: on Linux and macOS they are bytes, which need not be UTF-8. A handler hands such a value back as it got it, or builds one the same way.</li><li>Every other string is valid Unicode. JSON text has no byte order mark and no object repeats a key.</li><li>An optional field that is absent may be left out or be <code>null</code>.</li><li>Every integer of version 1 is below 2<sup>53</sup>, which a JavaScript number holds exactly.</li></ul><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><p>A handler that cannot answer a request answers with a JSON-RPC error; its <code>message</code> is what catter reports. catter ends the session when a handler answers with an error, with <code>abort</code> or with an action catter cannot take, stops (its output ends), writes what the protocol does not allow, or does not answer within <code>--handler-timeout</code>: the command being decided, and every command the build starts after it, fail without running, but under a backend that only observes the build, where every command has started by the time catter hears of it and the build runs on to its end; once the build has ended, catter ends the handlers&#39; input without a <code>finish</code>, prints the reason and exits 1.</p><p>An observer cannot answer a notification: one that fails exits, which catter reports when it next writes to it.</p>',39)])])}const u=t(c,[["render",r]]);export{p as __pageData,u as default};
